<?php
declare(strict_types=1);require __DIR__.'/config.php';
$sql='SELECT p.id,p.nom,p.type,p.description,p.prix_depart,p.date_debut,p.date_fin,COALESCE(MAX(e.montant),p.prix_depart) AS offre_actuelle,COUNT(e.id) AS nb_offres FROM produit p LEFT JOIN enchere e ON e.pid=p.id GROUP BY p.id,p.nom,p.type,p.description,p.prix_depart,p.date_debut,p.date_fin ORDER BY p.date_fin DESC,p.nom';
$rows=$db->query($sql);
?><!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Catalogue — Fedi Auctions</title><link rel="stylesheet" href="fedi.css"></head><body><header><a class="brand" href="index.php"><span>F</span> Fedi Auctions</a><nav><a href="index.php">Accueil</a><?php if(!empty($_SESSION['client_id'])):?><a href="propose.php">Faire une offre</a><?php else:?><a href="login.php">Connexion</a><?php endif;?></nav></header><main class="content wide"><p class="eyebrow">Les lots disponibles</p><h1>Catalogue des enchères</h1><div class="product-grid"><?php while($p=$rows->fetch_assoc()):$open=date('Y-m-d')>=$p['date_debut']&&date('Y-m-d')<=$p['date_fin'];?><article class="product"><div class="product-top"><span><?=h($p['type'])?></span><span class="status <?=$open?'open':'closed'?>"><?=$open?'En cours':(date('Y-m-d')<$p['date_debut']?'À venir':'Terminée')?></span></div><h2><?=h($p['nom'])?></h2><p><?=h((string)$p['description'])?></p><dl><div><dt>Prix de départ</dt><dd><?=number_format((float)$p['prix_depart'],0,',',' ')?> TND</dd></div><div><dt>Offre actuelle</dt><dd><?=number_format((float)$p['offre_actuelle'],0,',',' ')?> TND</dd></div><div><dt>Offres</dt><dd><?=(int)$p['nb_offres']?></dd></div><div><dt>Clôture</dt><dd><?=h($p['date_fin'])?></dd></div></dl><?php if($open):?><a class="text-link" href="propose.php?id=<?=(int)$p['id']?>">Enchérir →</a><?php endif;?></article><?php endwhile;?></div></main><footer>Fedi Auctions</footer></body></html>